    def value(self):
        temp = self.hex_name + '\x00'
        arduino.write(temp)
        return int(arduino.readline())

if __name__ == '__main__':
    arduino = serial.Serial('/dev/ttyACMO', 115200)

    encoder_one = Encoder('\x03')
